"Бабочка откладывает яйца.": "The butterfly lays eggs.",
"Бабочка откладывает яйца. Из яйца выходит гусеница. Гусеница превращается в куколку, а из куколки выходит бабочка.": "The butterfly lays eggs. A caterpillar comes out of the egg. The caterpillar turns into a pupa, and the butterfly comes out of the pupa.",
