"Большая часть Казахстана — степи. В степи много трав, например ковыля.": "Most of Kazakhstan is steppe. In the steppe there are many grasses, for example feather grass.",
"Бумага не притягивается.": "The paper is not attracted.",
"В Красную книгу Казахстана записаны редкие животные: снежный барс, архар и другие. Их охраняет закон.": "The Red Book of Kazakhstan lists rare animals: the snow leopard, the argali and others. They are protected by law.",
"В Красную книгу записаны редкие растения и животные. В Красной книге Казахстана есть тюльпан Грейга и яблоня Сиверса. Их нельзя рвать и выкапывать.": "Rare plants and animals are listed in the Red Book. The Red Book of Kazakhstan includes Greig's tulip and Sievers' apple tree. They must not be picked or dug up.",
"В воде растворяются сахар и соль. Камни и песок не растворяются.": "Sugar and salt dissolve in water. Stones and sand do not dissolve.",
"В воздухе есть кислород, которым мы дышим.": "The air contains oxygen, which we breathe.",
"В горах лежат ледники. Они хранят много пресной воды и питают реки.": "Glaciers lie in the mountains. They store a lot of fresh water and feed the rivers.",
"В двойных окнах между стёклами есть воздух. Он помогает сохранять тепло в комнате.": "In double windows there is air between the panes. It helps to keep the room warm.",
"В заповедниках и национальных парках природа под охраной. Один из них — Аксу-Жабаглы, самый старый в Казахстане.": "In nature reserves and national parks nature is protected. One of them is Aksu-Zhabagly, the oldest in Kazakhstan.",
"В интернете есть и верные, и неверные сведения. Искать лучше вместе со взрослым и проверять в нескольких источниках.": "On the internet there is both correct and incorrect information. It is better to search together with an adult and check in several sources.",
"В каких единицах измерят массу слона?": "In what units is the mass of an elephant measured?",
"В каких единицах измеряют массу?": "In what units is mass measured?",
"В каких единицах измеряют температуру?": "In what units is temperature measured?",
"В книгах и энциклопедиях собраны проверенные знания. Их написали учёные и авторы.": "Books and encyclopedias contain checked knowledge. They were written by scientists and authors.",
"В космосе расстояния огромные. Свет идёт от Солнца до Земли около восьми минут. Ракете до Луны лететь около трёх суток, а до Марса несколько месяцев.": "In space the distances are huge. Light takes about eight minutes to travel from the Sun to the Earth. A rocket takes about three days to fly to the Moon and several months to Mars.",
"В листьях на свету образуются питательные вещества. Через листья растение дышит.": "In the leaves, nutrients form in the light. The plant breathes through its leaves.",
"В минуте 60 секунд, в часе 60 минут, в сутках 24 часа, в неделе 7 суток, в году 12 месяцев.": "A minute has 60 seconds, an hour has 60 minutes, a day has 24 hours, a week has 7 days, a year has 12 months.",
"В музее можно увидеть настоящие предметы: кости, минералы, старинные вещи.": "In a museum you can see real objects: bones, minerals, ancient things.",
"В неделе семь суток. В году двенадцать месяцев.": "A week has seven days. A year has twelve months.",
"В одних сутках двадцать четыре часа. Это один оборот Земли вокруг оси.": "One day has twenty-four hours. This is one turn of the Earth around its axis.",
"В одной минуте шестьдесят секунд. В одном часе шестьдесят минут.": "One minute has sixty seconds. One hour has sixty minutes.",
"В почве корни держатся и берут питательные вещества.": "In the soil the roots hold on and take up nutrients.",
"В природе всё связано. Если исчезают одни животные, страдают другие. Нажимай на карточки.": "In nature everything is connected. If some animals disappear, others suffer. Tap the cards.",
"В стебле кактуса много…": "A cactus stem holds a lot of…",
"В тепле лёд тает и превращается в воду.": "In warmth ice melts and turns into water.",
"В тёплой комнате около двадцати градусов.": "A warm room is about twenty degrees.",
"В эксперименте мы сами создаём условия и смотрим, что получится. Он тоже начинается с цели. Нажимай на карточки.": "In an experiment we create the conditions ourselves and see what happens. It also begins with a goal. Tap the cards.",
"Ведём дневник погоды": "We keep a weather diary",
