"Верблюд живёт в пустыне. В горбах у него запас жира. Он долго может обходиться без воды.": "The camel lives in the desert. In its humps it has a store of fat. It can go a long time without water.",
"Верно ли?": "Is it true?",
"Весной распускаются почки и появляются листья": "In spring buds open and leaves appear",
"Весной тает снег. На деревьях распускаются почки, появляются первые листья и цветы. Трава начинает расти.": "In spring the snow melts. On the trees buds open, the first leaves and flowers appear. The grass begins to grow.",
"Ветви шиповника растут от земли.": "The branches of the dog rose grow from the ground.",
"Виктория": "Victoria",
"Вода бывает твёрдой, жидкой и газообразной. Нажимай на карточки.": "Water can be solid, liquid and gaseous. Tap the cards.",
"Вода в жидком состоянии течёт и принимает форму сосуда.": "Water in a liquid state flows and takes the shape of its container.",
"Вода в морях солёная, её нельзя пить. В Казахстане есть Каспийское море.": "The water in seas is salty, you cannot drink it. In Kazakhstan there is the Caspian Sea.",
"Вода в природе всё время путешествует.": "Water in nature is always travelling.",
"Вода есть в природе во многих местах. Нажимай на карточки.": "There is water in nature in many places. Tap the cards.",
"Вода испаряется и превращается в пар. Поэтому высыхают лужи и бельё на солнце.": "Water evaporates and turns into vapour. That is why puddles and washing dry in the sun.",
"Вода кипит при ста градусах. Кипяток очень горячий и опасный.": "Water boils at a hundred degrees. Boiling water is very hot and dangerous.",
"Вода стекает в реки и моря": "Water runs down into rivers and seas",
"Вода текучая: она переливается и течёт.": "Water is fluid: it can be poured and it flows.",
"Вода, воздух и солнечный свет — тоже важные ресурсы. Они нужны всем.": "Water, air and sunlight are also important resources. Everyone needs them.",
"Воду растение впитывает корнями. Без воды оно вянет.": "A plant takes in water through its roots. Without water it wilts.",
"Водяной пар — вода в газообразном состоянии. Вода кипит при ста градусах и превращается в пар.": "Water vapour is water in a gaseous state. Water boils at a hundred degrees and turns into vapour.",
"Воздух бесцветный и прозрачный. Голубым нам кажется небо, но не сам воздух.": "Air is colourless and transparent. The sky looks blue to us, but not the air itself.",
"Воздух бесцветный.": "Air is colourless.",
"Воздух вокруг нас": "The air around us",
"Воздух занимает место. Когда мы надуваем шарик, воздух заполняет его и растягивает.": "Air takes up space. When we blow up a balloon, air fills it and stretches it.",
"Воздух заполняет всё пространство.": "Air fills all the space.",
"Воздух имеет запах.": "Air has a smell.",
"Воздух имеет свою форму.": "Air has its own shape.",
"Воздух окружает нас везде, хотя мы его не видим. Нажимай на карточки.": "Air surrounds us everywhere, although we do not see it. Tap the cards.",
"Воздух плохо проводит тепло. Поэтому шубы, одеяла и пух греют: между волосками и перьями есть воздух.": "Air conducts heat poorly. That is why fur coats, blankets and down keep us warm: there is air between the hairs and feathers.",
"Воздух хорошо или плохо проводит тепло?": "Does air conduct heat well or poorly?",
"Воздух — это газ. Мы не можем его потрогать, но можем почувствовать, когда дует ветер.": "Air is a gas. We cannot touch it, but we can feel it when the wind blows.",
"Воздух — это жидкость.": "Air is a liquid.",
"Воздух — это…": "Air is…",
"Вокруг Земли есть воздушная оболочка. Она защищает от холода космоса и от вредных лучей Солнца.": "Around the Earth there is a shell of air. It protects against the cold of space and the Sun's harmful rays.",
"Вокруг Солнца вращаются восемь планет. Нажимай на карточки.": "Eight planets revolve around the Sun. Tap the cards.",
"Волчица рождает волчат.": "The she-wolf gives birth to wolf cubs.",
"Время и расстояния": "Time and distances",
"Время и расстояния в космосе": "Time and distances in space",
"Время измеряют секундами, минутами, часами, сутками, неделями, месяцами и годами. Нажимай на карточки.": "Time is measured in seconds, minutes, hours, days, weeks, months and years. Tap the cards.",
"Всем живым существам нужен воздух для дыхания. В воздухе есть кислород.": "All living things need air to breathe. Air contains oxygen.",
"Вспомни значение и свойства воздуха.": "Recall the meaning and properties of air.",
"Вспомни источники воды и как её беречь.": "Recall the sources of water and how to look after it.",
"Вспомни особенности планет.": "Recall the features of the planets.",
"Вспомни признаки каждого класса животных.": "Recall the features of each class of animals.",
"Вспомни свойства магнита и где он нужен.": "Recall the properties of a magnet and where it is needed.",
"Вспомни температуры, которые мы узнали.": "Recall the temperatures we have learned.",
"Вспомни, как отличаются деревья, кустарники и травы.": "Recall how trees, shrubs and grasses differ.",
"Вспомни, как развиваются разные животные.": "Recall how different animals develop.",
"Вспомни, какая вода: чистая, прозрачная, текучая.": "Recall what water is like: clean, transparent, fluid.",
"Вспомни, кто вокруг кого вращается.": "Recall who revolves around whom.",
"Вспомни, при какой температуре вода меняет состояние.": "Recall at what temperature water changes its state.",
"Вспомни, что делают скелет и мышцы.": "Recall what the skeleton and muscles do.",
"Вспомни, что происходит с растениями в каждое время года.": "Recall what happens to plants in each season.",
"Выбери верный ответ.": "Choose the correct answer.",
"Выбери знак, который подходит к погоде, или расшифруй знак.": "Choose the sign that matches the weather, or decode the sign.",
"Выбери класс, к которому относится животное.": "Choose the class the animal belongs to.",
"Выбери нужное качество или прибор.": "Choose the right quality or instrument.",
