"Фасоль, за которой мы смотрим, — это…": "The bean we are watching is…",
"Хлопок растёт на хлопчатнике.": "Cotton grows on the cotton plant.",
"Хомяк запасает зёрна.": "The hamster stores grain.",
"Хомяк и белка делают запасы корма на зиму.": "The hamster and the squirrel store food for the winter.",
"Цель — что мы хотим узнать. Например: как меняется погода за неделю.": "The goal is what we want to find out. For example: how the weather changes over a week.",
"Цель — что хотим узнать. Например: какие предметы тонут в воде?": "The goal is what we want to find out. For example: which objects sink in water?",
