"Чем можно измерить длину листа?": "What can you measure the length of a leaf with?",
"Чем узнать свою массу?": "What can you find your mass with?",
"Чем эксперимент отличается от наблюдения?": "How does an experiment differ from an observation?",
"Через какое окно в комнате будет светлее?": "Through which window will the room be lighter?",
"Через пять дней сравнить записи и сделать вывод": "After five days compare the notes and draw a conclusion",
"Череп защищает мозг. Рёбра защищают сердце и лёгкие. Позвоночник защищает спинной мозг.": "The skull protects the brain. The ribs protect the heart and lungs. The spine protects the spinal cord.",
"Черепахи откладывают яйца.": "Tortoises lay eggs.",
"Чистая вода не имеет вкуса. Вкус придают ей растворённые вещества: сахар, соль.": "Clean water has no taste. Dissolved substances give it taste: sugar, salt.",
"Чистая вода прозрачна.": "Clean water is transparent.",
"Чистая вода прозрачная. Сквозь неё видно дно.": "Clean water is transparent. You can see the bottom through it.",
"Чистить зубы нужно только тогда, когда они болят.": "Teeth should be cleaned only when they hurt.",
