"Чтобы быстро записывать, используют условные знаки: солнышко — ясно, облако — облачно, тучка с каплями — дождь, снежинка — снег.": "To write quickly, conventional signs are used: sun means clear, cloud means cloudy, cloud with drops means rain, snowflake means snow.",
"Чтобы выжить, животные приспосабливаются к тому месту, где живут. Нажимай на карточки.": "To survive, animals adapt to the place where they live. Tap the cards.",
"Чтобы кости и мышцы были крепкими, нужно двигаться, заниматься спортом и есть полезную еду.": "To keep bones and muscles strong, you need to move, do sport and eat healthy food.",
"Чтобы проверить, что нужно растению, ставим два одинаковых растения. Одному создаём условие, а другому нет. Потом сравниваем.": "To check what a plant needs, we set two identical plants. For one we create the condition, and for the other we do not. Then we compare.",
"Чтобы растение выросло, ему нужны определённые условия. Нажимай на карточки.": "For a plant to grow, it needs certain conditions. Tap the cards.",
"Чтобы увидеть результат, часто нужно подождать. Растение не вырастет за один день.": "To see the result you often need to wait. A plant will not grow in one day.",
