"Верно ли?<br><b>Воздух имеет запах.</b>": "Is it true?<br><b>Air has a smell.</b>",
"Верно ли?<br><b>Воздух имеет свою форму.</b>": "Is it true?<br><b>Air has its own shape.</b>",
"Верно ли?<br><b>Воздух — это жидкость.</b>": "Is it true?<br><b>Air is a liquid.</b>",
"Верно ли?<br><b>Для роста растению нужен свет.</b>": "Is it true?<br><b>A plant needs light to grow.</b>",
"Верно ли?<br><b>Зубы чистят утром и вечером.</b>": "Is it true?<br><b>Teeth are cleaned morning and evening.</b>",
"Верно ли?<br><b>Исследователь замечает мелочи.</b>": "Is it true?<br><b>An explorer notices details.</b>",
"Верно ли?<br><b>Исследователь записывает то, что хочет увидеть, а не то, что видит.</b>": "Is it true?<br><b>An explorer writes down what they want to see, not what they see.</b>",
"Верно ли?<br><b>Исследователь сдаётся сразу, если опыт не получился.</b>": "Is it true?<br><b>An explorer gives up at once if the experiment does not work.</b>",
