"Верно ли?<br><b>Молочные зубы можно не чистить, они всё равно выпадут.</b>": "Is it true?<br><b>Milk teeth need not be cleaned, they will fall out anyway.</b>",
"Верно ли?<br><b>Незнакомые ягоды можно пробовать на вкус.</b>": "Is it true?<br><b>Unfamiliar berries can be tasted.</b>",
"Верно ли?<br><b>Опыт с растением в темноте покажет, нужен ли ему свет.</b>": "Is it true?<br><b>An experiment with a plant in the dark will show whether it needs light.</b>",
"Верно ли?<br><b>Осанку нужно беречь с детства.</b>": "Is it true?<br><b>Posture must be looked after from childhood.</b>",
"Верно ли?<br><b>Растению не нужна почва: оно может расти на бумаге без воды.</b>": "Is it true?<br><b>A plant does not need soil: it can grow on paper without water.</b>",
"Верно ли?<br><b>Растению нужен воздух.</b>": "Is it true?<br><b>A plant needs air.</b>",
"Верно ли?<br><b>Растения могут расти совсем без воды.</b>": "Is it true?<br><b>Plants can grow without any water at all.</b>",
"Верно ли?<br><b>Руки нужно мыть с мылом.</b>": "Is it true?<br><b>Hands must be washed with soap.</b>",
"Верно ли?<br><b>Семена прорастают в тепле и во влажной почве.</b>": "Is it true?<br><b>Seeds sprout in warmth and in damp soil.</b>",
